"""Owner writing copy, isolated from translation and CMS work."""
def strings(lang):
    en=lang=='en'
    def t(fr,eng):return eng if en else fr
    return dict(flow=t('Deux décisions : le sujet et la rédaction, puis l’article et sa publication.','Two decisions: topic and writing, then the article and its publication.'),cost=t('Coût et limites de la rédaction','Writing cost and limits'),journey_topic=t('1. Sujet','1. Topic'),journey_article=t('2. Article','2. Article'),journey_publish=t('3. Publication','3. Publication'),next_publication=t('Relire et préparer la publication','Review and prepare publication'),track_publication=t('Suivre cet article','Track this article'),telegram=t('Valider dans Telegram','Approve in Telegram'),waiting=t('Décision 1/2 dans Telegram : le sujet et la rédaction. Le brouillon apparaîtra ici après votre accord.','Decision 1/2 in Telegram: topic and writing. The draft will appear here after approval.'),updates=t('Un nouvel état est disponible. Afficher la mise à jour','A new status is available. Show update'),title=t('Rédaction sourcée de Noyaru','Sourced writing for Noyaru'),publication=t('Publication du blog','Blog publication'),
        intro=t('Validez le sujet et la rédaction dans Telegram, puis relisez l’article avant sa publication.','Approve the topic and writing in Telegram, then review the article before publication.'),
        back=t('Référencement de Noyaru','Noyaru search visibility'),reload=t('Actualiser l’état','Refresh status'),
        scope=t('Cet espace prépare un texte privé. L’autorisation de rédaction ne permet aucune publication ni modification du site.','This workspace prepares private text. Writing authorization grants no publication or site changes.'),
        choose=t('Choisir un sujet','Choose a topic'),none=t('Aucun brief actuel relu à rédiger. Préparez et relisez un brief dans Référencement de Noyaru.','No current reviewed brief to write. Prepare and review a brief in Noyaru search visibility.'),
        dossier=t('Dossier transmis au rédacteur','Evidence sent to the writer'),source_info=t('Le sujet, la langue, les résumés et les titres de ressources ci-dessous seront transmis aux fournisseurs IA configurés. Les mesures Google/Bing, rapports et accès des comptes ne sont pas transmis.','The topic, language, summaries and resource titles below will be sent to the configured AI providers. Google/Bing metrics, reports and account credentials are not sent.'),
        catalog=t('Ressources déjà publiées','Already published resources'),catalog_limit=t('Échantillon limité à 20 titres ; la relecture doit comparer le sujet au catalogue complet.','Sample limited to 20 titles; review must compare the topic against the full catalogue.'),
        existing=t('Une demande existe déjà pour ces preuves. Retrouvez son état et la version enregistrée ci-dessous.','A request already exists for this evidence. Find its state and saved version below.'),find=t('Retrouver cette demande','Find this request'),
        limits=t('Plafond : 2 demandes de rédaction sur 24 heures glissantes, y compris pour le propriétaire ; 1 requête fournisseur au plus par autorisation, entrée bornée et 3 600 tokens de sortie au plus. Ce plafond ne fixe pas un montant en euros.','Limit: 2 writing requests per rolling 24 hours, including the owner; at most 1 provider request per authorization, bounded input and at most 3,600 output tokens. This does not set a monetary limit.'),
        used=t('Demandes réservées ou commencées dans cette fenêtre','Requests reserved or started in this window'),
        consent=t('Je valide ce sujet et autorise une rédaction avec les sources affichées, auprès du fournisseur IA configuré et avec son coût habituel. La proposition de publication se prépare en lecture seule. Je devrai encore relire et autoriser la publication. Validité : 24 heures.','I approve this topic and authorize one writing request with the displayed sources and configured AI provider at its usual cost. The publication proposal is prepared read-only. I must still review and authorize publication. Valid for 24 hours.'),
        authorize=t('Autoriser ce brouillon','Authorize this draft'),history=t('Brouillons et demandes','Drafts and requests'),
        language=t('Langue demandée','Requested language'),prepared=t('Autorisé le','Authorized on'),
        factual=t('Les références sont présentes, mais leur présence ne prouve pas les affirmations. Vérifiez leur portée, les formulations et l’utilité du texte avant de le relire.','References are present, but their presence does not prove the claims. Check their scope, wording and usefulness before reviewing the text.'),
        review_consent=t('J’ai vérifié le texte, les faits produit et le soutien de chaque affirmation par ses sources. Je marque cette version relue ; je n’autorise pas sa publication ici.','I checked the text, product facts and each claim against its sources. I mark this version reviewed; I do not authorize publication here.'),
        review=t('Marquer cette version relue','Mark this version reviewed'),cancel=t('Annuler ou écarter','Cancel or discard'),
        resume=t('Reprendre la demande autorisée','Resume the authorized request'),download=t('Exporter ce brouillon','Export this draft'),
        sources=t('Sources conservées','Saved sources'),pending=t('La demande continue en arrière-plan. Actualisez cet écran pour retrouver son état. Une reprise ne recommence pas un appel déjà parti.','The request continues in the background. Refresh this page to check its state. Resuming does not repeat a request already sent.'),
        stale=t('Le brief, la liaison ou les sources ont changé. Ce texte reste historique ; il ne peut pas être marqué relu avec ces preuves.','The brief, binding or sources changed. This text remains historical; it cannot be marked reviewed using this evidence.'),
        stop_info=t('Une demande déjà transmise au fournisseur peut finir ; son résultat ne sera pas retenu si l’autorisation ou les preuves ont changé.','A request already sent to the provider may finish; its result will not be retained if authorization or evidence changed.'),
        no_article=t('Aucun texte exploitable enregistré pour cette demande. Consultez son motif avant de décider de la suite.','No usable text was saved for this request. Check its reason before deciding what to do next.'),
        reviewed=t('Version relue. Retrouvez la décision de publication et le suivi de cet article.','Version reviewed. Continue to this article’s publication decision and tracking.'),
        statuses={k:t(fr,eng) for k,fr,eng in [('queued','En attente','Queued'),('running','Rédaction en cours','Writing'),('draft','À relire','Needs review'),('reviewed','Version relue','Version reviewed'),('rejected','Texte refusé','Text rejected'),('uncertain','Résultat fournisseur incertain','Provider result uncertain'),('stopped','Demande arrêtée','Request stopped'),('stale','Preuves changées','Evidence changed'),('cancelled','Annulé ou écarté','Cancelled or discarded')]},
        errors={k:t(fr,eng) for k,fr,eng in [
            ('confirm_required','Confirmez ce choix pour continuer.','Confirm this choice to continue.'),
            ('changed','La version affichée a changé. Actualisez cet écran.','The displayed version changed. Refresh this page.'),
            ('brief_required','Un brief actuel relu de type recherche ou guide est nécessaire.','A current reviewed search or guide brief is needed.'),
            ('evidence_changed','Les preuves ont changé ou ne sont plus actuelles. Revenez au brief.','Evidence changed or is no longer current. Return to the brief.'),
            ('paused','La préparation est en pause dans Référencement de Noyaru.','Preparation is paused in Noyaru search visibility.'),
            ('sources_required','Les repères officiels nécessaires ne sont pas tous actuels et validés. Consultez la veille SEO/GEO.','Required official guidance is not all current and approved. Check SEO/GEO knowledge.'),
            ('budget','Le plafond de rédaction sur 24 heures est atteint ou réservé. Aucun nouvel appel ne sera lancé pour ce choix.','The rolling 24-hour writing limit is reached or reserved. No new call will start for this choice.'),
            ('provider_missing','Aucun fournisseur IA de rédaction n’est configuré.','No writing AI provider is configured.'),
            ('provider_uncertain','Une requête a peut-être été traitée. Aucun repli ni nouvel essai automatique : vérifiez la consommation et le résultat avant d’intervenir.','A request may have been processed. No fallback or automatic retry: check usage and the result before intervening.'),
            ('invalid_output','La réponse ne respecte pas la structure, les références ou les limites attendues. Aucune publication n’a eu lieu.','The response violates the required structure, references or limits. Nothing was published.'),
            ('insufficient_sources','Le rédacteur n’a pas assez de preuves pour ce sujet. Complétez les repères validés avant une nouvelle demande.','The writer lacks evidence for this topic. Complete the approved guidance before another request.'),
            ('duplicate_article','Ce sujet renvoie à un article déjà présent dans le catalogue. Étudiez sa mise à jour.','This points to an article already in the catalogue. Consider updating it.'),
            ('request_limit','Le dossier dépasse les limites autorisées. Aucun appel supplémentaire n’est permis.','The request exceeds its limits. No additional call is permitted.'),
            ('authorization_ended','L’autorisation a expiré ou a été annulée.','Authorization expired or was cancelled.'),
            ('transport_missing','Le contrôle de la requête n’a pas été confirmé. La rédaction est arrêtée.','Request accounting was not confirmed. Writing stopped.'),
            ('tool_forbidden','Une action hors rédaction a été bloquée.','An action outside writing was blocked.'),
            ('unavailable','Cet espace est momentanément indisponible. Réessayez la consultation plus tard.','This workspace is temporarily unavailable. Try reading it later.') ]})
